import type {Repository} from '@github-ui/current-repository'
import {dismissRepositoryNoticePathPath, modelsSettingsPath} from '@github-ui/paths'
import {useNavigate} from '@github-ui/use-navigate'
import {useUser} from '@github-ui/use-user'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {Link, Banner} from '@primer/react'
import {useCallback, useState} from 'react'

type PaidUsageBannerProps = {
  dismissed: boolean | undefined
  repository: Repository
  businessSlug?: string
  className?: string
  rateLimitLink: string
}

export function PaidUsageBanner({
  dismissed = true,
  repository,
  businessSlug,
  className,
  rateLimitLink,
}: PaidUsageBannerProps) {
  const {currentUser} = useUser()
  const [bannerDismissed, setBannerDismissed] = useState(dismissed)
  const navigate = useNavigate()

  const repositoryId = repository?.id

  const handleDismiss = useCallback(() => {
    if (!currentUser || !repositoryId) return
    const fetch = async () => {
      const dismissPath = `${dismissRepositoryNoticePathPath(
        currentUser,
      )}?notice_name=github_models_paid_usage_banner_repo&repository_id=${repositoryId}`
      const response = await verifiedFetch(dismissPath, {
        method: 'DELETE',
      })
      if (response.ok) {
        setBannerDismissed(true)
      }
    }

    fetch()
  }, [currentUser, repositoryId])

  const navigateToModelSettings = () => {
    if (!repository) return
    const settingsPath = modelsSettingsPath(repository.isOrgOwned, repository.ownerLogin, businessSlug)
    navigate(settingsPath)
  }

  if (!currentUser || bannerDismissed) {
    return null
  }

  return (
    <Banner
      title="Enable Models paid usage"
      hideTitle
      variant="upsell"
      description={
        <>
          {businessSlug
            ? 'Your enterprise has'
            : repository.isOrgOwned
              ? 'Your organization has'
              : 'You currently have'}{' '}
          <Link href={rateLimitLink} inline>
            free rate limits
          </Link>
          . Enable Models paid usage to avoid interruptions.
        </>
      }
      primaryAction={<Banner.PrimaryAction onClick={navigateToModelSettings}>Enable paid usage</Banner.PrimaryAction>}
      onDismiss={handleDismiss}
      className={className}
    />
  )
}
