import {useCurrentRepository} from '@github-ui/current-repository'
import type {ModelDetails} from '@github-ui/github-models'
import {repoModelsPath} from '@github-ui/paths'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

export function useModelDetailsQuery(modelRegistry?: string, modelName?: string, modelPublisher?: string) {
  const repo = useCurrentRepository()
  const repoPath = repoModelsPath({repo, action: 'custom'})

  return useQuery<ModelDetails>({
    queryKey: ['github-models', 'models', modelRegistry, modelName, modelPublisher, repoPath],
    enabled: !!modelName && !!modelRegistry,
    async queryFn() {
      if (modelName === undefined || modelRegistry === undefined) return
      const path = getDetailsPath(repoPath, modelRegistry, modelName, modelPublisher)
      const res = await verifiedFetchJSON(path)
      if (!res.ok) throw new Error(await res.text())
      return res.json()
    },
  })
}

const getDetailsPath = (repoPath: string, modelRegistry: string, modelName: string, modelPublisher?: string) => {
  if (modelRegistry === 'custom') {
    if (!modelPublisher) {
      throw new Error('Model publisher is required for custom models')
    }
    return `${repoPath}/${modelPublisher}/${modelName}/details`
  }

  return `/marketplace/models/${modelRegistry}/${modelName}/details`
}
