import type {BannerProps} from '@primer/react'
import {createContext, use, useMemo, useState} from 'react'

export type Banner = {
  variant: Extract<BannerProps['variant'], 'success' | 'critical' | 'info'>
  message: string
  description?: React.ReactNode
}

interface PromptBannersContextType {
  banner?: Banner
  setBanner: (banner?: Banner) => void
  bannerHeight: string
}

const PromptBannersContext = createContext<PromptBannersContextType>({
  banner: undefined,
  setBanner: () => undefined,
  bannerHeight: '0px',
})

export function usePromptsBanner() {
  return use(PromptBannersContext)
}

export function PromptsBannersProvider({children}: {children: React.ReactNode}) {
  const [banner, setBanner] = useState<Banner>()
  // Banner height is 36px + (8px * 2) [for padding] + 16px [for padding between elements]
  const bannerHeight = banner ? '68px' : '0px'
  const value = useMemo(() => ({banner, setBanner, bannerHeight}), [banner, setBanner, bannerHeight])
  return <PromptBannersContext value={value}>{children}</PromptBannersContext>
}
