import {CurrentRepositoryProvider} from '@github-ui/current-repository'
import {PaidUsageBanner} from '@github-ui/github-models/PaidUsageBanner'
import {modelsCatalogPath, repoModelsPath} from '@github-ui/paths'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {Link, useLocation, useMatch, useResolvedPath} from '@github-ui/react-router'
import {
  AppsIcon,
  ArrowUpRightIcon,
  CommandPaletteIcon,
  HomeIcon,
  NoteIcon,
  SidebarExpandIcon,
} from '@primer/octicons-react'
import {Heading, IconButton, Label, NavList, PageLayout, type PageLayoutContentProps} from '@primer/react'
import {clsx} from 'clsx'
import type {PropsWithChildren} from 'react'
import {aboutGitHubModelsDocsUrl} from '../constants'
import type {ModelRepoPayload} from '../types'
import styles from './ModelsRepoLayout.module.css'

function NavItem({
  to,
  children,
  icon,
  trailingIcon,
}: {
  to: string
  children: React.ReactNode
  icon: React.ReactNode
  trailingIcon?: React.ReactNode
}) {
  const resolved = useResolvedPath(to)
  let isCurrent = !!useMatch({path: resolved.pathname, end: true})

  const currentPath = useLocation().pathname

  // Special case for playground route since `models/playground` redirects to `models/:publisher/:modelName/playground`
  if (to.endsWith('/playground')) {
    const playgroundPathRegex = /^\/[^/]+\/[^/]+\/models\/[^/]+\/[^/]+\/playground$/ // Matches `/:owner/:repo/models/:publisher/:modelName/playground`
    isCurrent = playgroundPathRegex.test(currentPath)
  }

  return (
    <NavList.Item href={to} aria-current={isCurrent ? 'page' : undefined}>
      <NavList.LeadingVisual>{icon}</NavList.LeadingVisual>
      {children}
      {trailingIcon ? <NavList.TrailingVisual>{trailingIcon}</NavList.TrailingVisual> : null}
    </NavList.Item>
  )
}

export function ModelsRepoLayout({
  children,
  fileTreeExpanded,
  setFileTreeExpanded,
  width = 'large' as const,
}: PropsWithChildren<{
  fileTreeExpanded: boolean
  setFileTreeExpanded: (expanded: boolean) => void
  width?: PageLayoutContentProps['width']
}>) {
  const {repository, canEdit, paidUsageBannerDismissed, businessSlug, isMarketplaceEnabled, rateLimitLink} =
    useAppPayload<ModelRepoPayload>()
  const marketplacePath = isMarketplaceEnabled ? '/marketplace/models' : null
  const playgroundPath = canEdit ? repoModelsPath({repo: repository, action: 'playground'}) : marketplacePath

  return (
    <CurrentRepositoryProvider repository={repository}>
      <PageLayout containerWidth="full" columnGap="none" padding="none">
        {fileTreeExpanded && (
          <PageLayout.Pane
            padding="condensed"
            position="start"
            hidden={{
              narrow: true,
              regular: false,
              wide: false,
            }}
            divider="line"
            sticky
          >
            <div className="d-flex flex-column height-full tmp-pl-3 tmp-pt-3">
              <div className="d-flex flex-justify-between">
                <Heading as="h2" className="f3" id="pane-heading">
                  <div className="d-flex flex-items-center">
                    Models{' '}
                    <Label variant="success" className="ml-2">
                      Preview
                    </Label>
                  </div>
                </Heading>
                <IconButton
                  onClick={() => setFileTreeExpanded(false)}
                  aria-label="Collapse menu"
                  icon={SidebarExpandIcon}
                  variant="invisible"
                />
              </div>
              <NavList className="flex-1">
                <NavItem
                  to={repoModelsPath({
                    repo: repository,
                    action: '',
                  })}
                  icon={<HomeIcon />}
                >
                  Overview
                </NavItem>
                <NavItem
                  to={repoModelsPath({
                    repo: repository,
                    action: 'prompts',
                  })}
                  icon={<NoteIcon />}
                >
                  Prompts
                </NavItem>
                {playgroundPath && (
                  <NavItem
                    to={playgroundPath}
                    icon={<CommandPaletteIcon />}
                    trailingIcon={canEdit ? undefined : <ArrowUpRightIcon />}
                  >
                    Playground
                  </NavItem>
                )}
                <NavList.Divider />
                {isMarketplaceEnabled && (
                  <NavItem to={modelsCatalogPath()} icon={<AppsIcon />} trailingIcon={<ArrowUpRightIcon />}>
                    Catalog
                  </NavItem>
                )}
              </NavList>
              <div className="d-flex flex-justify-between my-2">
                <div>
                  <Link to={aboutGitHubModelsDocsUrl}>Docs</Link>
                  <span className="mx-1">·</span>
                  <Link to="https://github.com/orgs/community/discussions/categories/models">Share feedback</Link>
                </div>
              </div>
            </div>
          </PageLayout.Pane>
        )}
        <PageLayout.Content
          className={clsx(styles.content, 'fill-page-height')}
          padding="condensed"
          width={width}
          as="section"
        >
          <div className="fill-page-height" data-hpc>
            <PaidUsageBanner
              dismissed={paidUsageBannerDismissed}
              repository={repository}
              businessSlug={businessSlug}
              className={clsx('mb-2', width !== 'full' && (fileTreeExpanded ? 'tmp-mr-5' : 'tmp-mx-5'))}
              rateLimitLink={rateLimitLink}
            />
            {children}
          </div>
        </PageLayout.Content>
      </PageLayout>
    </CurrentRepositoryProvider>
  )
}
