import type {RepoModel, ResponseFormat} from '../../types'

function doesModelNameMatch(targetName: string, model: RepoModel): boolean {
  const normalizedTargetName = targetName.toLowerCase()
  // Try to find a model by its name or original name (name is original_name with any `.` replaced by `-`)
  return model.original_name.toLowerCase() === normalizedTargetName || model.name.toLowerCase() === normalizedTargetName
}

function doesModelPublisherMatch(targetPublisher: string, model: RepoModel): boolean {
  return model.publisherSlug.toLowerCase() === targetPublisher.toLowerCase()
}

export function findModel(modelId: string, models: RepoModel[]): RepoModel | undefined {
  // First try to find by publisher/name. Might have been given an id like
  // 'azureml://registries/azure-openai/models/gpt-4o-mini/versions/2024-07-18' or a registry/publisher/name combo.
  if (modelId.includes('/')) {
    const parts = modelId.split('/')

    if (parts.length === 2 || parts.length === 3) {
      // Registry is optional
      const registry = parts.at(-3)

      const publisher = parts.at(-2)!
      const name = parts.at(-1)!
      const model = models.find(m => {
        if (registry !== undefined) {
          if (m.registry !== registry) {
            return false
          }
        }

        return doesModelPublisherMatch(publisher, m) && doesModelNameMatch(name, m)
      })
      if (model) {
        return model
      }
    }
  }

  // Then try to find by id
  const model = models.find(x => x.id === modelId)
  if (model) return model

  // Then by its name or original name
  return models.find(x => doesModelNameMatch(modelId, x))
}

/**
 * Get an identifier for a model to be used as the 'model' field in a prompt YAML file.
 */
export function promptModelIdentifierFor(
  model: Pick<RepoModel, 'registry' | 'publisherSlug' | 'original_name' | 'isCustom'>,
): string {
  const segments: string[] = []

  if (model.isCustom) {
    segments.push(model.registry)
  }

  segments.push(model.publisherSlug)
  segments.push(model.original_name)

  return `${segments.join('/')}`
}

/**
 * Get a supported response format for the specified model, using the preferred response format from the prompt if
 * it's supported.
 */
export function responseFormatFor(model: RepoModel, promptResponseFormat: ResponseFormat): ResponseFormat {
  if (promptResponseFormat === 'text') return promptResponseFormat
  if (promptResponseFormat === 'json_object' && model.capabilities?.structuredOutput) return promptResponseFormat
  if (promptResponseFormat === 'json_schema' && model.capabilities?.jsonSchemaStructuredOutput) {
    return promptResponseFormat
  }
  return 'text'
}
