import type {PathFunction} from '@github-ui/paths'

/**
 * Returns a relative URL for viewing or modifying the GitHub Models settings for a repository.
 * Keep in sync with the `create_repo_models_settings_path` route helper in Rails.
 */
export const repositoryModelsSettingsPath: PathFunction<{owner: string; repo: string}> = ({owner, repo}) =>
  `/${owner}/${repo}/models/settings`
