import {useMutation} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {SetUserSettingsPayload, UserSettings} from '../types'
import {repositoryModelsSettingsPath} from '../paths'

export function useUpdateRepoModelsSettings(owner: string, repo: string) {
  const path = repositoryModelsSettingsPath({owner, repo})
  return useMutation({
    mutationKey: ['update-github-models-settings', owner, repo],
    mutationFn: async (payload: SetUserSettingsPayload) => {
      const result = await verifiedFetchJSON(path, {
        method: 'POST',
        body: payload,
        headers: {'Content-Type': 'application/json'},
      })
      if (result.ok) {
        return (await result.json()) as UserSettings
      }
      throw new Error(`${result.status} on ${result.url}, unexpected status or payload`)
    },
  })
}

export function closeSampleBannerPayload(): SetUserSettingsPayload {
  return {key: 'SAMPLE_BANNER_CLOSED', value: 'true'}
}
